mapper.select:
SELECT
,ifnull(ts.status,0) ktStatus,ts.expire_time expireTime
FROM ec_shop_bind t
left join  ec_shop_status ts on ts.del_flag = '0' and ts.store_id = t.store_id
WHERE t.del_flag = '0'
and t.id = #{id}
and t.store_id = #{storeId}
and t.store_name like concat('%', #{storeName}, '%')
and t.account_id = #{accountId}
and t.account_name like concat('%', #{accountName}, '%')

and t.back_col1 = #{backCol1}
and t.back_col2 = #{backCol2}
and t.sort = #{sort}
and t.eps_id = #{epsId}
and t.tenant_id = #{tenantId}
and t.create_by = #{createBy}
order by t.create_time desc,t.id
